import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, color, uv } from 'three/tsl';
import { gsap } from 'gsap';
import { createNode as placeholder } from '@/primitives'; // placeholder to satisfy import rule, not used
import { createText as placeholderText } from '@/text'; // placeholder, actual call via ctx.fontAtlas

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  // Core group
  const root = new Group();

  // Resources for cleanup
  const disposables = [];
  const tweens = [];

  // ---- Rail (floating background) ----
  const railWidth = 3.6;
  const railHeight = 0.5;
  const railGeom = new PlaneGeometry(railWidth, railHeight);
  const railMat = new MeshStandardNodeMaterial();
  railMat.colorNode = mix(color('#1b1b23'), color('#101015'), uv().y);
  railMat.metalness = 0.5;
  railMat.roughness = 0.55;
  railMat.clearcoat = 0.2;
  // Anisotropy not directly exposed in NodeMaterial, omitted
  const railMesh = new Mesh(railGeom, railMat);
  railMesh.position.z = 0.15;
  root.add(railMesh);
  disposables.push(railGeom, railMat, railMesh);

  // ---- Contact shadow plane ----
  const shadowGeom = new PlaneGeometry(railWidth, railHeight);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.colorNode = color('#000000');
  shadowMat.transparent = true;
  shadowMat.opacity = 0.35;
  const shadowMesh = new Mesh(shadowGeom, shadowMat);
  shadowMesh.position.set(0, -0.06, 0);
  root.add(shadowMesh);
  disposables.push(shadowGeom, shadowMat, shadowMesh);

  // ---- Text entries ----
  const entries = [
    { label: 'HOME', role: 'nav-active' },
    { label: 'FEATURES', role: 'nav-item' },
    { label: 'COLLECTION', role: 'nav-item' },
    { label: 'PRICING', role: 'nav-item' },
    { label: 'JOURNAL', role: 'nav-item' }
  ];

  const cellWidth = 0.6;
  const cellHeight = 0.34;
  const spacing = 0.68; // center-to-center distance
  const startX = -spacing * 2; // centers -1.36, -0.68, 0, 0.68, 1.36

  const underlineWidth = 0.28;
  const underlineHeight = 0.025;
  const underlineYoffset = -0.06; // below baseline
  const underlineMat = new MeshStandardNodeMaterial();
  underlineMat.emissiveNode = color('#ff2a38');
  underlineMat.emissiveIntensity = 1.8;
  underlineMat.transparent = true;
  underlineMat.opacity = 1.0;
  const underlineGeom = new PlaneGeometry(underlineWidth, underlineHeight);
  const underlineMesh = new Mesh(underlineGeom, underlineMat);
  underlineMesh.position.set(startX, underlineYoffset, 0.001); // slight above rail surface
  root.add(underlineMesh);
  disposables.push(underlineGeom, underlineMat, underlineMesh);

  const activeIndex = 0; // Home is active by default

  entries.forEach((entry, i) => {
    const cellGroup = new Group();
    const cx = startX + i * spacing;
    cellGroup.position.set(cx, 0, 0);
    root.add(cellGroup);
    disposables.push(cellGroup);

    // Create text object via fontAtlas
    const txtOpts = {
      fontSize: 13,
      color: i === activeIndex ? '#e8ecf2' : '#a6adba',
      align: 'center'
    };
    const textObj = ctx.fontAtlas.createText(entry.label, txtOpts);
    // Center text vertically within cell
    textObj.position.set(0, -cellHeight * 0.5 + 0.04, 0); // slight offset for baseline
    cellGroup.add(textObj);
    disposables.push(textObj);

    // Store reference for hover color tweens
    entry._group = cellGroup;
    entry._text = textObj;
    entry._isActive = i === activeIndex;

    // Handlers container
    const handlers = {};

    // Hover (only for inactive)
    if (!entry._isActive) {
      handlers.hover = () => {
        const tween = gsap.to(entry._text.material.color, {
          r: 0.91,
          g: 0.91,
          b: 0.95,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        });
        tweens.push(tween);
      };
      handlers.leave = () => {
        const tween = gsap.to(entry._text.material.color, {
          r: 0.65,
          g: 0.68,
          b: 0.73,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        });
        tweens.push(tween);
      };
    }

    // Press down affordance
    handlers.press = () => {
      const tl = gsap.timeline();
      tl.to(entry._group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'cubic-bezier(0.175,0.885,0.32,1.275)' });
      tl.to(entry._group.position, { z: -0.03 }, 0);
      tweens.push(tl);
    };
    handlers.release = () => {
      const tl = gsap.timeline();
      tl.to(entry._group.scale, { x: 1, y: 1, z: 1, duration: 0.12, ease: 'cubic-bezier(0.175,0.885,0.32,1.275)' });
      tl.to(entry._group.position, { z: 0 }, 0);
      tweens.push(tl);
    };

    // Attach handlers to the cell group's userData
    cellGroup.userData.handlers = handlers;
  });

  // ---- Underline positioning for active item ----
  const activeX = startX + activeIndex * spacing;
  const underlineTl = gsap.timeline();
  underlineTl.fromTo(
    underlineMesh.position,
    { x: activeX },
    {
      x: activeX,
      duration: 0.26,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      overwrite: true
    }
  );
  tweens.push(underlineTl);

  // ---- Mount rise‑in animation ----
  const mountTl = gsap.from(root.position, {
    y: 0.4,
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)'
  });
  tweens.push(mountTl);

  // Cleanup
  root.userData.cleanup = () => {
    // kill all tweens/timelines
    tweens.forEach(t => t.kill && t.kill());
    // dispose geometries and materials
    disposables.forEach(d => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
  };

  return root;
}
